sp_widget.client_script:
api.controller = function () {
    var c = this;

    var PHONE_PATTERN = /^[0-9]{10}$/;

    c.view = 'form';
    c.submitting = false;
    c.searching = false;
    c.serverErrors = [];
    c.clientErrors = {};
    c.search = { number: '' };

    c.form = {
        citizen_name: '',
        citizen_phone: '',
        grievance_category: '',
        short_description: '',
        description: ''
    };

    if (c.data.receipt) {
        c.view = 'receipt';
    }

    // Explicit c.* phone check in addition to ng-pattern, so the inline
    // help-block message is driven by controller state too.
    c.validatePhone = function () {
        var value = (c.form.citizen_phone || '') + '';
        if (!value) {
            c.clientErrors.citizen_phone = 'Mobile number is required.';
        } else if (!PHONE_PATTERN.test(value.trim())) {
            c.clientErrors.citizen_phone = 'Enter exactly 10 digits (0-9), with no spaces or symbols.';
        } else {
            c.clientErrors.citizen_phone = '';
        }
        return !c.clientErrors.citizen_phone;
    };

    c.isFormValid = function () {
        return !!(
            (c.form.citizen_name || '').trim() &&
            (c.form.grievance_category || '').trim() &&
            (c.form.short_description || '').trim() &&
            (c.form.description || '').trim() &&
            PHONE_PATTERN.test(((c.form.citizen_phone || '') + '').trim())
        );
    };

    c.submit = function () {
        c.serverErrors = [];
        if (!c.validatePhone() || !c.isFormValid()) {
            return;
        }

        c.submitting = true;

        // Fields MUST be assigned onto c.data before calling c.server.update()
        c.data.action = 'submit_grievance';
        c.data.citizen_name = c.form.citizen_name;
        c.data.citizen_phone = c.form.citizen_phone;
        c.data.grievance_category = c.form.grievance_category;
        c.data.short_description = c.form.short_description;
        c.data.description = c.form.description;

        c.server.update().then(function () {
            c.submitting = false;
            c.data.action = null;

            var result = c.data.submitResult;
            if (result && result.success) {
                c.view = 'receipt';
                c.resetFormFields();
            } else if (result && result.errors) {
                c.serverErrors = result.errors;
            } else {
                c.serverErrors = ['Your grievance could not be submitted. Please try again.'];
            }
        });
    };

    // Server round-trip so the filter is applied by the query, not just in the DOM
    c.runSearch = function () {
        c.searching = true;
        c.data.action = 'search_grievances';
        c.data.searchNumber = c.search.number;

        c.server.update().then(function () {
            c.searching = false;
            c.data.action = null;
        });
    };

    c.clearSearch = function () {
        c.search.number = '';
        c.runSearch();
    };

    c.newGrievance = function () {
        c.data.receipt = null;
        c.serverErrors = [];
        c.clientErrors = {};
        c.resetFormFields();
        c.view = 'form';
    };

    c.resetFormFields = function () {
        c.form = {
            citizen_name: '',
            citizen_phone: '',
            grievance_category: '',
            short_description: '',
            description: ''
        };
        c.clientErrors = {};
    };
};

sp_widget.css:
.grievance-intake {
    .panel-title {
        font-size: $font-size-large;
        margin: 0;
    }

    .grievance-alert-title {
        margin: 0 0 6px;
        font-weight: 600;
    }

    .grievance-error-list {
        margin: 0;
        padding-left: 18px;
    }

    .grievance-textarea {
        resize: vertical;
    }

    /* ---------- Tamper-evident receipt ---------- */
    .grievance-receipt {
        .grievance-receipt-lead {
            font-size: $font-size-large;
            margin-bottom: 16px;
        }

        .grievance-receipt-facts {
            margin-bottom: 12px;

            dt {
                font-size: $font-size-small;
                text-transform: uppercase;
                letter-spacing: 0.04em;
                color: $text-muted;
            }

            dd {
                margin-bottom: 12px;
                word-break: break-word;
            }
        }

        .grievance-receipt-number {
            font-size: $font-size-large;
            font-weight: 700;
            color: $brand-success;
        }

        .grievance-receipt-note {
            font-size: $font-size-small;
        }
    }

    .grievance-hash-block {
        display: block;
        padding: 10px 12px;
        font-family: $font-family-monospace;
        font-size: $font-size-small;
        line-height: 1.5;
        word-break: break-all;
        word-wrap: break-word;
        background-color: $pre-bg;
        border: 1px solid $table-border-color;
        border-radius: $border-radius-base;
        color: $text-color;
    }

    /* ---------- Tracker ---------- */
    .grievance-tracker {
        .grievance-search {
            margin-bottom: 14px;
        }

        .grievance-table {
            font-size: $font-size-small;

            th {
                white-space: nowrap;
            }

            .grievance-cell-number {
                font-weight: 600;
                white-space: nowrap;
            }

            .label {
                font-size: $font-size-small;
            }
        }

        .grievance-hash-inline {
            font-family: $font-family-monospace;
            font-size: $font-size-small;
            cursor: help;
            background-color: transparent;
            color: $text-muted;
            padding: 0;
        }

        .grievance-empty {
            padding: 18px 0;
        }

        .grievance-asof {
            margin: 8px 0 0;
            font-size: $font-size-small;
            text-align: right;
        }
    }
}

sp_widget.script:
(function () {
    var TABLE = 'x_1850267_public_0_grievance';

    // Server-side truth for the category choice list (never trust the client payload)
    var CATEGORY_CHOICES = [
        { label: 'Water', value: 'water' },
        { label: 'Electricity', value: 'electricity' },
        { label: 'Sanitation', value: 'sanitation' },
        { label: 'Roads', value: 'roads' }
    ];

    // Each state value maps to its own Bootstrap 3 label class so the badge
    // actually communicates meaning instead of rendering one flat colour.
    var STATE_CLASS_MAP = {
        '1': 'label-info', // Open
        '2': 'label-warning', // Work in Progress
        '3': 'label-success', // Closed Complete
        '4': 'label-danger', // Closed Incomplete
        '7': 'label-default', // Closed Skipped
        '-5': 'label-default' // Pending
    };

    // Escalation is an integer choice 0-3; 3 is the overdue/breached tier.
    var ESCALATION_CLASS_MAP = {
        '0': 'label-default',
        '1': 'label-info',
        '2': 'label-warning',
        '3': 'label-danger'
    };

    // Exactly 10 numeric digits. The client enforces the same rule via ng-pattern,
    // but the client is never trusted - this is the authoritative check.
    var PHONE_PATTERN = /^[0-9]{10}$/;

    var HASH_PREVIEW_LENGTH = 12;

    // Anti-spam: at most 5 grievances per citizen per rolling 24 hours.
    var RATE_LIMIT_MAX = 5;
    var RATE_LIMIT_SECONDS = 86400;

    // Initialise every data.* property so the template never binds to undefined
    data.categories = CATEGORY_CHOICES;
    data.grievances = [];
    data.receipt = null;
    data.submitResult = null;
    data.searchApplied = '';
    data.rowLimit = 25;
    data.asOf = '';

    var action = input && input.action ? input.action + '' : '';

    if (action === 'submit_grievance') {
        data.submitResult = submitGrievance(input);
        if (data.submitResult.success) {
            data.receipt = data.submitResult.receipt;
        }
    } else if (action === 'search_grievances') {
        data.searchApplied = trim(input && input.searchNumber);
    }

    // Always (re)load the tracker so the list reflects the latest state after
    // a submit or a search round-trip.
    data.grievances = loadGrievances(data.searchApplied);
    data.asOf = new GlideDateTime().getDisplayValue();

    // ------------------------------------------------------------------
    // Submission
    // ------------------------------------------------------------------
    function submitGrievance(payload) {
        var citizenName = trim(payload.citizen_name);
        var citizenPhone = trim(payload.citizen_phone);
        var category = trim(payload.grievance_category);
        var shortDescription = trim(payload.short_description);
        var description = trim(payload.description);

        var errors = [];

        if (!citizenName) {
            errors.push('Full name is required.');
        }

        if (!citizenPhone) {
            errors.push('Mobile number is required.');
        } else if (!PHONE_PATTERN.test(citizenPhone)) {
            errors.push('Mobile number must be exactly 10 digits (0-9), with no spaces or symbols.');
        }

        if (!category) {
            errors.push('Grievance category is required.');
        } else if (!isValidCategory(category)) {
            errors.push('Select a valid grievance category.');
        }

        if (!shortDescription) {
            errors.push('Summary is required.');
        }

        if (!description) {
            errors.push('Detailed description is required.');
        }

        if (errors.length > 0) {
            return { success: false, errors: errors };
        }

        // Anti-spam rate limit: block a 6th submission inside a rolling 24h window.
        // Checked after field validation so a spammer gets the same feedback order
        // as a legitimate user, and before insert so nothing is written.
        if (isRateLimited()) {
            return {
                success: false,
                rateLimited: true,
                errors: [
                    'Rate limit reached: you may submit at most ' +
                        RATE_LIMIT_MAX +
                        ' grievances within a 24-hour period.'
                ]
            };
        }

        var gr = new GlideRecord(TABLE);
        gr.initialize();
        gr.setValue('citizen_name', citizenName.substring(0, 100));
        gr.setValue('citizen_phone', citizenPhone);
        gr.setValue('grievance_category', category);
        gr.setValue('short_description', shortDescription.substring(0, 160));
        gr.setValue('description', description.substring(0, 4000));

        var sysId = gr.insert();
        if (!sysId) {
            return {
                success: false,
                errors: ['Your grievance could not be submitted. You may not have permission to create a grievance.']
            };
        }

        // cryptographic_hash and target_resolution are populated by before-insert
        // business rules, so the record MUST be re-read to obtain them.
        var receiptGr = new GlideRecordSecure(TABLE);
        receiptGr.addQuery('sys_id', sysId);
        receiptGr.setLimit(1);
        receiptGr.query();

        if (!receiptGr.next()) {
            return {
                success: false,
                errors: ['Your grievance was saved, but the receipt could not be retrieved. Use the tracker below to find it.']
            };
        }

        return {
            success: true,
            receipt: {
                sys_id: sysId + '',
                number: receiptGr.getValue('number') || '',
                target_resolution: receiptGr.getDisplayValue('target_resolution') || '',
                cryptographic_hash: receiptGr.getValue('cryptographic_hash') || ''
            }
        };
    }

    // ------------------------------------------------------------------
    // My grievances tracker
    // ------------------------------------------------------------------
    function loadGrievances(searchNumber) {
        var rows = [];

        var gr = new GlideRecordSecure(TABLE);
        gr.addQuery('opened_by', gs.getUserID());
        if (searchNumber) {
            gr.addQuery('number', 'CONTAINS', searchNumber);
        }
        gr.orderByDesc('sys_created_on');
        gr.setLimit(25);
        gr.query();

        while (gr.next()) {
            var stateValue = gr.getValue('state') + '';
            var escalationValue = gr.getValue('escalation') + '';
            var isActive = gr.getValue('active') === '1' || gr.getValue('active') === 'true';
            var hash = gr.getValue('cryptographic_hash') || '';
            var closeNotes = gr.getValue('close_notes') || '';
            var resolved = stateValue === '3' || !isActive;

            rows.push({
                sys_id: gr.getUniqueValue() + '',
                number: gr.getValue('number') || '',
                category: gr.getDisplayValue('grievance_category') || '',
                short_description: gr.getValue('short_description') || '',
                state: gr.getDisplayValue('state') || '',
                stateClass: STATE_CLASS_MAP[stateValue] || 'label-default',
                target_resolution: gr.getDisplayValue('target_resolution') || '',
                escalation: gr.getDisplayValue('escalation') || '',
                escalationClass: ESCALATION_CLASS_MAP[escalationValue] || 'label-default',
                resolved: resolved,
                close_notes: resolved ? closeNotes : '',
                hash_full: hash,
                hash_short: hash ? hash.substring(0, HASH_PREVIEW_LENGTH) + '...' : ''
            });
        }

        return rows;
    }

    // ------------------------------------------------------------------
    // Anti-spam rate limiting
    // ------------------------------------------------------------------
    /**
     * True when the current user has already opened RATE_LIMIT_MAX or more
     * grievances in the trailing 24 hours.
     *
     * Uses new GlideDateTime() (scoped-safe) rather than gs.nowDateTime(), and
     * counts with GlideAggregate so no rows are fetched just to be tallied.
     * The window is rolling (now minus 24h), not a calendar day, so a citizen
     * cannot reset their quota at midnight.
     */
    function isRateLimited() {
        var cutoff = new GlideDateTime();
        cutoff.addSeconds(-RATE_LIMIT_SECONDS);

        var ga = new GlideAggregate(TABLE);
        ga.addQuery('opened_by', gs.getUserID());
        ga.addQuery('sys_created_on', '>=', cutoff.getValue());
        ga.addAggregate('COUNT');
        ga.query();

        var recentCount = 0;
        if (ga.next()) {
            recentCount = parseInt(ga.getAggregate('COUNT'), 10) || 0;
        }

        return recentCount >= RATE_LIMIT_MAX;
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------
    function trim(value) {
        if (value === null || value === undefined) {
            return '';
        }
        return (value + '').trim();
    }

    function isValidCategory(value) {
        for (var i = 0; i < CATEGORY_CHOICES.length; i++) {
            if (CATEGORY_CHOICES[i].value === value) {
                return true;
            }
        }
        return false;
    }
})();
